-- Replace only previous default copy; preserve owner-written content and historical data.
UPDATE documents SET data=jsonb_set(data,'{contactIntro}',to_jsonb('Have a role, an idea, or a technical challenge in mind? Connect with me on social media.'::text)) WHERE key='settings' AND data->>'contactIntro'='Have a role, an idea, or a technical challenge in mind? Tell me a little about it.';
UPDATE documents SET data=jsonb_set(data,'{privacy}',to_jsonb('This portfolio displays professional information and media. It does not collect or store visitor messages. Contact takes place directly on external social platforms, which apply their own privacy policies. No advertising trackers are installed. Owner Studio uses a private login session cookie; your theme preference is stored in your browser.'::text)) WHERE key='settings' AND data->>'privacy'='Contact details are used only to respond to your inquiry. Messages are stored privately on this website’s server for up to 180 days. Contact the owner to request deletion. No advertising trackers are installed. Optional email notifications share your inquiry with the configured email provider. This site does not operate an AI chat assistant.';
